def boxes(grid):
    from collections import Counter
    bg=Counter(v for r in grid for v in r).most_common(1)[0][0]
    H,W=len(grid),len(grid[0])
    seen=[[False]*W for _ in range(H)]; out=[]
    for r in range(H):
        for c in range(W):
            if grid[r][c]!=bg and not seen[r][c]:
                col=grid[r][c]; stack=[(r,c)]; seen[r][c]=True; comp=[]
                while stack:
                    x,y=stack.pop(); comp.append((x,y))
                    for dx,dy in((1,0),(-1,0),(0,1),(0,-1)):
                        a,b=x+dx,y+dy
                        if 0<=a<H and 0<=b<W and not seen[a][b] and grid[a][b]==col:
                            seen[a][b]=True; stack.append((a,b))
                rs=[p[0] for p in comp]; cs=[p[1] for p in comp]
                t,l,b,rr=min(rs),min(cs),max(rs),max(cs)
                h,w=b-t+1,rr-l+1
                # hollow rectangle check
                border={(x,y) for x in range(t,b+1) for y in range(l,rr+1)
                        if x in(t,b) or y in(l,rr)}
                if set(comp)==border and h>=3 and w>=3:
                    out.append((t,l,h,w,col))
    return out,bg

def fill(grid):
    grid=[row[:] for row in grid]
    bs,bg=boxes(grid)
    for t,l,h,w,col in bs:
        f=2 if h%2==0 else 7
        for r in range(t+1,t+h-1):
            for c in range(l+1,l+w-1):
                grid[r][c]=f
    return grid

